        return None

    def scan_points(obj, out, depth=0):
        if depth > 4:
            return
        p = as_point(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                scan_points(v, out, depth + 1)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                scan_points(v, out, depth + 1)

    def get_first_point(obj, keys):
        if not isinstance(obj, dict):
            return None
        for k in keys:
            v = obj.get(k)
            pts = []
            scan_points(v, pts)
            if pts:
                return pts[0]
        return None

    def collect_points(obj, keys):
        pts = []
        if isinstance(obj, dict):
            for k in keys:
                scan_points(obj.get(k), pts)
        return pts

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    pos = get_first_point(observation, [
        "position", "pos", "loc", "location", "agent_pos", "agent_position",
        "self_pos", "self_position", "me", "player_pos", "player_position"
    ])
    if pos is None:
