    resources = collect_points(observation, [
        "resources", "resource", "food", "items", "targets", "goal", "goals",
        "collectibles", "collectable", "pickup", "pickups", "treasure"
    ])
    threats = collect_points(observation, [
        "enemies", "enemy", "opponents", "opponent", "hazards", "hazard",
        "threats", "threat", "monsters", "monster", "predators"
    ])
    allies = collect_points(observation, ["allies", "ally", "teammates", "friends"])

