    threats = [p for p in threats if p != pos]
    resources = [p for p in resources if p != pos]
    allies = [p for p in allies if p != pos]

    # Infer bounds / center if possible
    width = None
    height = None
    grid = observation.get("grid") if isinstance(observation, dict) else None
    if isinstance(grid, (list, tuple)) and grid:
        height = len(grid)
        first_row = grid[0]
